def solve(a, b):
    # Initialize the matrix to store distances
    dp = [[0 for _ in range(len(b) + 1)] for _ in range(len(a) + 1)]

    # Fill the matrix
    for i in range(len(a) + 1):
        for j in range(len(b) + 1):
            if i == 0:
                dp[i][j] = j  # Min. operations = j inserts on empty a to get b
            elif j == 0:
                dp[i][j] = i  # Min. operations = i deletes on a to get empty b
            elif a[i-1] == b[j-1]:
                dp[i][j] = dp[i-1][j-1]  # Characters match, no operation needed
            else:
                dp[i][j] = min(dp[i][j-1],  # Insert
                               dp[i-1][j],  # Delete
                               dp[i-1][j-1]) + 1  # Substitute

    # The answer is in the bottom-right cell of the matrix
    return dp[len(a)][len(b)]
