            while i < len(s) and s[i].isdigit():
                num = num * 10 + int(s[i])
                i += 1
            if i < len(s) and s[i] in units:
                total_seconds += num * units[s[i]]
                i += 1
            else:
                raise ValueError("Number without a unit")
        elif s[i] in units:
            if i > 0 and s[i-1] in units:
                raise ValueError("Repeated units")
            total_seconds += units[s[i]]
            i += 1
        else:
            raise ValueError("Unknown unit")

    return total_seconds
