import heapq

def shortest(graph, start, goal):
    if start == goal:
        return (0, [start])

    pq = [(0, start, [])]
    visited = set()

    while pq:
        (dist, current, path) = heapq.heappop(pq)
        if current == goal:
            return (dist, path + [current])
        if current in visited:
            continue
        visited.add(current)
        for neighbor, weight in graph[current]:
            heapq.heappush(pq, (dist + weight, neighbor, path + [current]))

    return (None, [])
